import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import { Alert, Image, ScrollView, StyleSheet, Switch, Text, TextInput, TouchableOpacity, View } from "react-native";
import { router } from "expo-router";
import { useEffect, useMemo, useState } from "react";
import * as ImagePicker from "expo-image-picker";
import { ScreenContainer } from "@/components/screen-container";
import { djangoApi } from "@/lib/django-api";

type Section={id:number;title:string;section_type:string;config:Record<string,any>;sort_order:number;is_visible:boolean};
const TYPES=[{id:"hero",label:"Hero"},{id:"banner",label:"بانر"},{id:"category",label:"فئات"},{id:"product_grid",label:"منتجات"},{id:"trend",label:"ترند"}];

type Draft={title:string;type:string;subtitle:string;imageUrl:string;button:string;url:string;categoryNames:string;visible:boolean};
const EMPTY_DRAFT:Draft={title:"",type:"banner",subtitle:"",imageUrl:"",button:"",url:"",categoryNames:"",visible:true};

export default function VendorStorefrontScreen(){
  const [sections,setSections]=useState<Section[]>([]); const [loading,setLoading]=useState(true); const [selected,setSelected]=useState<number|null>(null); const [draft,setDraft]=useState<Draft>(EMPTY_DRAFT);
  async function load(){try{setLoading(true);const data=await djangoApi<Section[]|{results?:Section[]}>("/api/storefront-sections/");const list=Array.isArray(data)?data:(data.results??[]);setSections(list.sort((a,b)=>a.sort_order-b.sort_order));}catch(error){Alert.alert("تعذر تحميل المتجر",error instanceof Error?error.message:"حدث خطأ")}finally{setLoading(false)}}
  useEffect(()=>{load()},[]);
  function edit(section:Section){setSelected(section.id);const c=section.config||{};const circles=Array.isArray(c.circles)?c.circles:[];setDraft({title:section.title,type:section.section_type,subtitle:String(c.subtitle||""),imageUrl:String(c.image_url||c.imageUrl||""),button:String(c.button_label||c.ctaLabel||""),url:String(c.target_url||c.url||""),categoryNames:circles.map((item:any)=>String(item.title||"")).filter(Boolean).join(", "),visible:section.is_visible})}
  async function create(){try{const data=await djangoApi<Section>("/api/storefront-sections/",{method:"POST",body:JSON.stringify({title:"قسم جديد",section_type:"banner",config:{subtitle:"",image_url:"",button_label:"",target_url:"",slides:[],circles:[],cards:[],actions:[],promo:{enabled:false}},sort_order:sections.length,is_visible:true})});setSections(s=>[...s,data]);edit(data)}catch(error){Alert.alert("تعذر إنشاء القسم",error instanceof Error?error.message:"حدث خطأ")}}
  async function pickImage(){const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:["images"],allowsEditing:true,quality:0.8,base64:true});if(!result.canceled&&result.assets[0]?.base64){setDraft(d=>({...d,imageUrl:`data:${result.assets[0].mimeType||"image/jpeg"};base64,${result.assets[0].base64}`}));}}
  async function save(){
    if(selected===null)return;
    const previous=sections.find(s=>s.id===selected)?.config||{};
    const names=draft.categoryNames.split(",").map(x=>x.trim()).filter(Boolean);
    const base={...previous,subtitle:draft.subtitle,image_url:draft.imageUrl,button_label:draft.button,target_url:draft.url,__editor_version:2};
    if(draft.type==="category"){
      base.circles=names.map((name,index)=>({id:`${selected}::circle::${index}-${Date.now()}`,title:name,targetCategory:name,url:draft.url||`/collection?category=${encodeURIComponent(name)}`,imageUrl:draft.imageUrl,visible:true,sortOrder:index}));
      base.slides=[];
      base.cards=[];
    } else if(draft.type==="hero"||draft.type==="banner"){
      base.slides=draft.imageUrl?[{id:`${selected}::slide::${Date.now()}`,title:draft.title,subtitle:draft.subtitle,ctaLabel:draft.button||"تسوّق الآن",url:draft.url||"",imageUrl:draft.imageUrl,visible:true,sortOrder:0}]:[];
    }
    try{const data=await djangoApi<Section>(`/api/storefront-sections/${selected}/`,{method:"PATCH",body:JSON.stringify({title:draft.title,section_type:draft.type,config:base,is_visible:draft.visible})});setSections(s=>s.map(x=>x.id===data.id?data:x));Alert.alert("تم الحفظ","تم تحديث القسم ونشره بالبنية الصحيحة للتطبيق.")}catch(error){Alert.alert("تعذر الحفظ",error instanceof Error?error.message:"تحقق من البيانات.")}
  }
  async function move(id:number,dir:-1|1){const ordered=[...sections].sort((a,b)=>a.sort_order-b.sort_order);const i=ordered.findIndex(x=>x.id===id);const j=i+dir;if(i<0||j<0||j>=ordered.length)return;[ordered[i],ordered[j]]=[ordered[j],ordered[i]];try{await Promise.all(ordered.map((x,index)=>djangoApi(`/api/storefront-sections/${x.id}/`,{method:"PATCH",body:JSON.stringify({sort_order:index})})));setSections(ordered.map((x,index)=>({...x,sort_order:index})));}catch{Alert.alert("تعذر الترتيب","حاول مجددًا.")}}
  const current=useMemo(()=>sections.find(s=>s.id===selected),[sections,selected]);
  return <ScreenContainer className="bg-[#F6F7F9]" edges={["top","bottom","left","right"]}><View style={styles.header}><TouchableOpacity onPress={()=>router.back()}><MaterialIcons name="arrow-forward" size={23} color="#111"/></TouchableOpacity><Text style={styles.title}>تصميم واجهة المتجر</Text><TouchableOpacity onPress={create}><MaterialIcons name="add" size={23} color="#E60023"/></TouchableOpacity></View>{loading?<View style={styles.center}><Text style={styles.muted}>جارٍ التحميل...</Text></View>:<ScrollView style={styles.scroll} contentContainerStyle={styles.page} keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator><View style={styles.preview}><Text style={styles.previewHead}>معاينة الهاتف</Text>{sections.filter(s=>s.is_visible).map(s=><Preview key={s.id} section={s}/>)}</View><View style={styles.list}>{sections.map((s,index)=><View key={s.id} style={[styles.sectionCard,selected===s.id&&styles.selected]}><TouchableOpacity style={styles.cardTop} onPress={()=>edit(s)}><View style={[styles.typePill,{backgroundColor:s.is_visible?"#ECF8F1":"#F3F4F6"}]}><Text style={styles.typeText}>{TYPES.find(t=>t.id===s.section_type)?.label||s.section_type}</Text></View><View style={styles.cardCopy}><Text style={styles.cardTitle}>{s.title||"قسم بدون عنوان"}</Text><Text style={styles.cardMeta}>{s.is_visible?"ظاهر":"مخفي"} · #{index+1}</Text></View><MaterialIcons name="drag-handle" size={22} color="#BBB"/></TouchableOpacity><View style={styles.moveRow}><TouchableOpacity onPress={()=>move(s.id,-1)} disabled={index===0} style={styles.smallBtn}><MaterialIcons name="keyboard-arrow-up" size={19} color={index===0?"#DDD":"#555"}/></TouchableOpacity><TouchableOpacity onPress={()=>move(s.id,1)} disabled={index===sections.length-1} style={styles.smallBtn}><MaterialIcons name="keyboard-arrow-down" size={19} color={index===sections.length-1?"#DDD":"#555"}/></TouchableOpacity><Switch value={s.is_visible} onValueChange={async value=>{await djangoApi(`/api/storefront-sections/${s.id}/`,{method:"PATCH",body:JSON.stringify({is_visible:value})});setSections(cs=>cs.map(x=>x.id===s.id?{...x,is_visible:value}:x))}} trackColor={{true:"#168451"}}/><Text style={styles.switchLabel}>إظهار</Text></View></View>)}</View>{current&&<View style={styles.editor}><Text style={styles.editorTitle}>تحرير القسم</Text><TextInput value={draft.title} onChangeText={v=>setDraft(d=>({...d,title:v}))} style={styles.input} placeholder="عنوان القسم" textAlign="right"/><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.typeRow}>{TYPES.map(t=><TouchableOpacity key={t.id} onPress={()=>setDraft(d=>({...d,type:t.id}))} style={[styles.typeBtn,draft.type===t.id&&styles.typeBtnActive]}><Text style={[styles.typeBtnText,draft.type===t.id&&styles.typeBtnTextActive]}>{t.label}</Text></TouchableOpacity>)}</ScrollView>{draft.type==="category"?<TextInput value={draft.categoryNames} onChangeText={v=>setDraft(d=>({...d,categoryNames:v}))} style={styles.input} placeholder="الفئات مفصولة بفواصل: أحذية، حقائب، ساعات" textAlign="right"/>:null}<TouchableOpacity onPress={pickImage} style={styles.imageButton}><Text style={{color:draft.imageUrl?"#111":"#888",fontSize:13,flex:1,textAlign:"right"}} numberOfLines={1}>{draft.imageUrl?(draft.imageUrl.startsWith("data:")?"صورة جديدة محددة":draft.imageUrl):"اختر صورة القسم..."}</Text><MaterialIcons name="photo-library" size={20} color="#E60023"/></TouchableOpacity><TextInput value={draft.subtitle} onChangeText={v=>setDraft(d=>({...d,subtitle:v}))} style={[styles.input,styles.multi]} placeholder="النص الفرعي" textAlign="right" multiline/><TextInput value={draft.button} onChangeText={v=>setDraft(d=>({...d,button:v}))} style={styles.input} placeholder="نص الزر" textAlign="right"/><TextInput value={draft.url} onChangeText={v=>setDraft(d=>({...d,url:v}))} style={styles.input} placeholder="الرابط /collection أو https://..." textAlign="left" autoCapitalize="none"/><View style={styles.saveRow}><View style={styles.visibleRow}><Switch value={draft.visible} onValueChange={v=>setDraft(d=>({...d,visible:v}))} trackColor={{true:"#168451"}}/><Text>ظاهر للعملاء</Text></View><TouchableOpacity style={styles.save} onPress={save}><Text style={styles.saveText}>حفظ ونشر</Text></TouchableOpacity></View></View>}</ScrollView>}</ScreenContainer>}
function Preview({section}:{section:Section}){const c=section.config||{};const circles=Array.isArray(c.circles)?c.circles:[];return <View style={styles.pSection}>{section.section_type==="category"&&circles.length?<ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.pCircles}>{circles.map((item:any)=><View key={String(item.id)} style={styles.pCircleItem}><View style={styles.pCircle}>{item.imageUrl?<Image source={{uri:String(item.imageUrl)}} style={StyleSheet.absoluteFillObject}/>:<MaterialIcons name="category" size={22} color="#777"/>}</View><Text numberOfLines={1} style={styles.pCircleText}>{String(item.title||"")}</Text></View>)}</ScrollView>:<>{c.image_url?<Image source={{uri:String(c.image_url)}} style={styles.pImage}/>:<View style={styles.pImageFallback}><MaterialIcons name="image" size={28} color="#BBB"/></View>}<View style={styles.pBody}><Text style={styles.pTitle}>{section.title}</Text>{c.subtitle?<Text style={styles.pSub}>{String(c.subtitle)}</Text>:null}{c.button_label?<View style={styles.pButton}><Text style={styles.pButtonText}>{String(c.button_label)}</Text></View>:null}</View></>}</View>}
const styles=StyleSheet.create({header:{height:58,backgroundColor:"#FFF",paddingHorizontal:15,flexDirection:"row",justifyContent:"space-between",alignItems:"center",borderBottomWidth:1,borderColor:"#EEE"},title:{fontSize:17,fontWeight:"900",color:"#111"},scroll:{flex:1,minHeight:0},page:{padding:12,paddingBottom:220,maxWidth:900,width:"100%",alignSelf:"center",gap:12,flexGrow:1},preview:{backgroundColor:"#111",borderRadius:18,padding:14},previewHead:{color:"#FFF",fontWeight:"900",textAlign:"right",marginBottom:8},pSection:{backgroundColor:"#FFF",borderRadius:14,overflow:"hidden",marginBottom:9},pImage:{width:"100%",height:120},pImageFallback:{height:90,backgroundColor:"#F0F0F0",alignItems:"center",justifyContent:"center"},pBody:{padding:11,alignItems:"flex-end"},pTitle:{fontSize:13,fontWeight:"900",color:"#111"},pSub:{fontSize:10,color:"#777",marginTop:3,textAlign:"right"},pButton:{marginTop:8,backgroundColor:"#111",paddingHorizontal:11,paddingVertical:7,borderRadius:18},pButtonText:{color:"#FFF",fontSize:10,fontWeight:"800"},pCircles:{padding:12,gap:12},pCircleItem:{width:64,alignItems:"center"},pCircle:{width:56,height:56,borderRadius:28,backgroundColor:"#F0F0F0",overflow:"hidden",alignItems:"center",justifyContent:"center"},pCircleText:{fontSize:9,color:"#444",marginTop:5,textAlign:"center"},list:{gap:8},sectionCard:{backgroundColor:"#FFF",borderRadius:13,padding:11,borderWidth:1,borderColor:"#EEE"},selected:{borderColor:"#111"},cardTop:{flexDirection:"row-reverse",alignItems:"center",gap:10},cardCopy:{flex:1,alignItems:"flex-end",minWidth:0},cardTitle:{fontSize:13,fontWeight:"900",color:"#222"},cardMeta:{fontSize:10,color:"#999",marginTop:3},typePill:{paddingHorizontal:8,paddingVertical:5,borderRadius:99},typeText:{fontSize:9,fontWeight:"800",color:"#333"},moveRow:{flexDirection:"row-reverse",alignItems:"center",gap:5,marginTop:8},smallBtn:{width:34,height:32,borderWidth:1,borderColor:"#E6E6E6",borderRadius:9,alignItems:"center",justifyContent:"center"},switchLabel:{fontSize:10,color:"#666",marginLeft:4},editor:{backgroundColor:"#FFF",borderRadius:14,padding:14},editorTitle:{fontSize:16,fontWeight:"900",textAlign:"right",marginBottom:12},input:{backgroundColor:"#F7F7F8",borderWidth:1,borderColor:"#E2E2E2",borderRadius:10,paddingHorizontal:12,paddingVertical:10,fontSize:13,marginBottom:9,minWidth:0},multi:{minHeight:72,textAlignVertical:"top"},typeRow:{gap:7,paddingBottom:4},typeBtn:{paddingHorizontal:12,paddingVertical:8,borderRadius:18,borderWidth:1,borderColor:"#DDD"},typeBtnActive:{backgroundColor:"#111",borderColor:"#111"},typeBtnText:{fontSize:10,color:"#666",fontWeight:"700"},typeBtnTextActive:{color:"#FFF"},imageButton:{backgroundColor:"#F7F7F8",borderWidth:1,borderColor:"#E2E2E2",borderRadius:10,paddingHorizontal:12,paddingVertical:11,marginBottom:9,flexDirection:"row-reverse",alignItems:"center",gap:8},saveRow:{flexDirection:"row-reverse",alignItems:"center",justifyContent:"space-between",gap:10,marginTop:5},visibleRow:{flexDirection:"row-reverse",alignItems:"center",gap:5},save:{flex:1,backgroundColor:"#E60023",paddingVertical:13,borderRadius:10,alignItems:"center"},saveText:{color:"#FFF",fontWeight:"900"},center:{flex:1,alignItems:"center",justifyContent:"center"},muted:{color:"#888"}});
